    "每天按本地日期重置，默认 100 封，可设置 1–1000。失败和取消的请求也计数；缓存命中和手动摘要不计数。超过上限的邮件不会自动补处理。": "每天按本地日期重置，默认 100 封，可设置 1–1000。失败和取消的请求也计数；缓存命中和手动摘要不计数。超过上限的邮件不会自动补处理。",
