    "此别名已用于其他标签，请先移除冲突规则。": "This alias is already used for another tag. Remove the conflicting rule first.",
    "目标标签已删除": "Target tag deleted",
    "请先在 Thunderbird 中创建标签。": "Create tags in Thunderbird first.",
    "标签别名操作失败，请重试。": "Tag alias operation failed. Please retry.",
    "别名规则已保存。": "Alias rules saved.",
