    "点击“开始改写”后，仅选中文字和改写要求会发送给 OpenAI，使用你授权的 ChatGPT 套餐额度。不会自动发送邮件。": "Starting a rewrite sends only the input text shown above and your instructions to OpenAI using your authorized ChatGPT plan. Emails are never sent automatically.",
