    "本软件为独立开发的非官方工具，与 OpenAI、Mozilla 或 Thunderbird 无隶属或背书关系。AI 输出可能包含错误，请在替换或发送邮件前自行核对。": "This is an independently developed, unofficial tool, not affiliated with or endorsed by OpenAI, Mozilla or Thunderbird. AI output may contain errors. Review it before replacing text or sending email.",
