    "软件按原样提供，不作任何保证；责任限制以 MIT 许可证为准。使用 各模型 服务仍须遵守其适用条款。": "The software is provided as is, without warranty. Liability limitations are governed by the MIT License. Use of each model service remains subject to its applicable terms.",
