    "用于之后自动生成的标签，不修改已有标签。": "Applies to future AI-generated tags; existing tags are unchanged.",
    "新邮件自动标签": "Automatically tag new mail",
    "仅对勾选账户收件箱中新收到的邮件自动添加标签，新账户默认关闭，不扫描历史邮件。使用当前提供商、模型及标签语言；启用后会自动发送邮件主题和正文，消耗套餐或 API 额度。": "Automatically tag new arrivals in the inboxes of selected accounts only. New accounts are disabled by default; existing mail is not scanned. Uses the current provider, model and tag language. Enabling sends subjects and bodies automatically and consumes plan or API quota.",
    "没有可用的邮件账户。": "No supported mail accounts available.",
    "无法读取账户列表。": "Could not load accounts.",
    "最近自动标签处理成功。": "Last automatic tagging succeeded.",
    "最近自动标签处理失败，请检查设置或手动重试。": "Last automatic tagging failed. Check settings or retry manually.",
    "在邮箱主界面右键账户名称，选择“AI 助手 → 自动标记新邮件”以开启或关闭。仅处理已启用账户收件箱的新邮件，新账户默认关闭，不扫描历史邮件。使用当前提供商、模型及标签语言；启用后自动发送邮件主题和正文，消耗套餐或 API 额度。": "Right-click an account name in the main mail window and choose AI Assist → Automatically tag new mail to enable or disable. Only new inbox mail in enabled accounts is processed. New accounts are off by default; existing mail is not scanned. Uses the current provider, model and tag language; subjects and bodies are sent automatically and consume plan or API quota.",
