    "摘要与翻译缓存": "Summary and translation cache",
    "缓存长期保存在本机。再次打开时优先使用匹配的结果；点击重试才重新生成。清除缓存后需重新生成。": "The cache stays on this computer. Reopening uses matching results; Retry regenerates them. Clearing the cache requires regeneration.",
