    "Gemini API 免费层取决于项目和模型；已启用计费的项目可能产生费用，不使用网页订阅额度。": "Gemini API の無料枠はプロジェクトとモデルによって異なります。課金を有効にしたプロジェクトでは料金が発生する場合があります。ウェブ版のサブスクリプション枠は使用しません。",
    "Claude API 通常另行计费，不包含在 Claude Free、Pro 或 Max 网页订阅中。": "Claude API は通常別料金で、Claude Free、Pro、Max のウェブ版プランには含まれません。",
    "请在设置页填写所选提供商的 API Key。": "設定ページに選択した提供元の API キーを入力してください。",
    "API Key 无效，请检查并重新保存。": "API キーが無効です。確認して保存し直してください。",
    "API 权限不足，请检查密钥、项目、地区或账户权限。": "API 権限が不足しています。キー、プロジェクト、地域、アカウント権限を確認してください。",
    "API 额度不足或请求过多，请查看提供商用量与计费设置。": "API の利用枠不足、またはリクエスト過多です。提供元の利用状況と課金設定を確認してください。",
    "所选 API 模型不可用，请在设置页重新选择。": "選択した API モデルは利用できません。設定ページで選び直してください。",
    "提供商拒绝了请求，请检查所选模型是否支持文字生成。": "提供元がリクエストを拒否しました。モデルがテキスト生成に対応しているか確認してください。",
    "无法连接 API，请检查网络后重试。": "API に接続できません。ネットワークを確認して再試行してください。",
    "API 服务暂时不可用，请稍后重试。": "API サービスは一時的に利用できません。後で再試行してください。",
    "未获得完整可用的文字结果，可能被安全策略阻止。": "利用可能な完全なテキストが返されませんでした。安全ポリシーで制限された可能性があります。",
    "提供商设置无效，请在设置页重新选择。": "提供元の設定が無効です。設定ページで選び直してください。",
    "软件按原样提供，不作任何保证；责任限制以 MIT 许可证为准。使用 各模型 服务仍须遵守其适用条款。": "本ソフトウェアは現状のまま、保証なしで提供されます。責任の制限は MIT ライセンスに従います。各モデルサービスの利用には、その利用規約も適用されます。",
    "邮箱 AI 助手": "Mail AI Assist",
    "摘要、翻译、添加标签和辅助撰写邮件。": "AI でメールの要約、翻訳、タグ付け、作成を支援します。",
    "AI 摘要": "AI 要約",
