    "仅发送当前邮件主题和正文，不处理附件。AI 结果请自行核对。": "現在のメールの件名と本文のみを送信し、添付ファイルは処理しません。AI の結果を確認してください。タグ生成では既存タグを優先するため、その名前も送信します。",
