    "邮件翻译自动识别原文语言；摘要使用界面语言。": "翻訳では原文の言語を自動検出し、要約では表示言語を使用します。",
    "用于之后自动生成的标签，不修改已有标签。": "今後自動生成するタグに適用します。既存のタグは変更しません。",
    "新邮件自动标签": "新着メールの自動タグ付け",
    "仅对勾选账户收件箱中新收到的邮件自动添加标签，新账户默认关闭，不扫描历史邮件。使用当前提供商、模型及标签语言；启用后会自动发送邮件主题和正文，消耗套餐或 API 额度。": "選択したアカウントの受信トレイに届く新着メールだけに自動でタグを付けます。新規アカウントは既定で無効で、過去のメールは走査しません。現在の提供元、モデル、タグ言語を使用します。有効にすると件名と本文を自動送信し、プランまたは API の利用枠を消費します。",
    "没有可用的邮件账户。": "利用可能なメールアカウントがありません。",
