    "最近自动标签处理成功。": "前回の自動タグ付けに成功しました。",
    "最近自动标签处理失败，请检查设置或手动重试。": "前回の自動タグ付けに失敗しました。設定を確認するか手動で再試行してください。",
    "在邮箱主界面右键账户名称，选择“AI 助手 → 自动标记新邮件”以开启或关闭。仅处理已启用账户收件箱的新邮件，新账户默认关闭，不扫描历史邮件。使用当前提供商、模型及标签语言；启用后自动发送邮件主题和正文，消耗套餐或 API 额度。": "メイン画面でアカウント名を右クリックし「AI アシスタント → 新着メールの自動タグ付け」で切り替えます。有効なアカウントの受信トレイの新着メールだけを処理します。新規アカウントは既定で無効で、過去のメールは走査しません。現在の提供元、モデル、タグ言語を使用し、件名と本文を自動送信してプランまたは API の利用枠を消費します。",
