    "desktop_cleanup_failed": "今回のエクスポートを完全に削除できません。閉じる操作を中止しました。ファイルのパスを確認して再試行してください。",
    "在文件夹中显示": "フォルダーで表示",
    "复制文件路径": "ファイルのパスをコピー",
    "选择目标聊天后，将文件拖入输入区；也可复制路径，在添加文件对话框中粘贴。": "対象チャットを選び、ファイルを入力欄へドラッグしてください。パスをコピーしてファイル追加画面に貼り付けることもできます。",
    "无法打开文件夹，请复制文件路径手动添加。": "フォルダーを開けません。ファイルのパスをコピーして手動で追加してください。",
    "路径已复制。请在目标聊天的添加文件对话框中粘贴并打开。": "パスをコピーしました。対象チャットのファイル追加画面に貼り付けて開いてください。",
    "复制失败，路径已选中，请按 Ctrl+C 复制。": "コピーに失敗しました。パスを選択したので Ctrl+C でコピーしてください。",
    "导出邮件": "メールをエクスポート",
    "TXT 导出正文，可排除引用；EML 保留完整原始邮件及附件，不过滤引用。": "TXT は本文を出力し、引用を除外できます。EML は引用を除外せず、元のメールと添付ファイルを完全に保持します。",
    "摘要与翻译缓存": "要約と翻訳のキャッシュ",
    "缓存长期保存在本机。再次打开时优先使用匹配的结果；点击重试才重新生成。清除缓存后需重新生成。": "キャッシュはこのコンピューターに保存されます。再度開くと一致する結果を優先し、「再試行」で再生成します。キャッシュを消去すると再生成が必要になります。",
    "打开缓存文件夹": "キャッシュフォルダーを開く",
    "清除缓存": "キャッシュを消去",
