    "缓存条目": "キャッシュ件数",
    "缓存操作失败，请检查本地辅助程序。": "キャッシュ操作に失敗しました。ローカルヘルパーを確認してください。",
    "已加载缓存。点击重试可重新生成。": "キャッシュから読み込みました。「再試行」で再生成できます。",
    "结果已生成，但未保存到缓存。": "結果を生成しましたが、キャッシュに保存できませんでした。",
    "在账户右键菜单中勾选“自动为新邮件生成 AI 摘要”可启用。所有账户默认关闭；仅处理收件箱的新邮件，使用当前模型与界面语言，并消耗套餐或 API 额度。": "アカウントの右クリックメニューで AI 自動要約を有効にできます。全アカウントで初期状態は無効です。受信トレイの新着メールのみを現在のモデルと表示言語で処理し、プランまたは API の利用枠を消費します。",
    "最近自动摘要处理成功。": "前回の自動要約に成功しました。",
    "最近自动摘要处理失败，请检查设置或手动重试。": "前回の自動要約に失敗しました。設定を確認するか手動で再試行してください。",
    "Google 翻译已配置，将优先使用。": "Google 翻訳が設定済みで、優先して使用します。",
    "未配置 Google 翻译，使用当前 AI 模型。": "Google 翻訳は未設定です。現在の AI モデルを使用します。",
    "配置后优先使用 Google 官方翻译；未配置时使用当前 AI 模型。请求失败时不自动切换服务。需要启用 Google Cloud 结算，NMT 每月前 50 万字符免费，超额收费。Key 在本机加密保存。": "設定済みの場合は Google 公式翻訳を優先し、未設定の場合は現在の AI モデルを使用します。失敗時に自動で切り替えません。Google Cloud の課金設定が必要です。NMT は毎月最初の 50 万文字が無料で、超過分は有料です。キーはこのコンピューターに暗号化して保存します。",
    "google_access": "Google がリクエストを拒否しました。キー、Cloud Translation API の有効化、制限、課金設定を確認してください。",
    "google_quota": "Google 翻訳の利用上限またはリクエスト制限に達しました。後で再試行してください。",
    "google_failed": "Google 翻訳に失敗しました。ローカルヘルパーとネットワークを確認して再試行してください。",
    "翻译服务商": "翻訳サービス提供元",
    "无": "なし",
    "微软翻译 (Azure) API": "Microsoft Translator (Azure) API",
    "Azure 资源区域": "Azure リソースのリージョン",
    "区域或多服务资源必须填写 Region，例如 westeurope；全局资源留空。": "地域またはマルチサービスのリソースではリージョン（例：westeurope）が必要です。グローバルリソースの場合は空欄にしてください。",
    "DeepL 根据 Key 自动识别 API Free 或 Pro。": "キーから DeepL API Free または Pro を自動判別します。",
    "所选翻译服务商已配置，将优先使用。": "選択した翻訳サービスが設定済みで、優先して使用します。",
    "未选择或未配置翻译服务商，使用当前 AI 模型。": "翻訳サービスが未選択または未設定です。現在の AI モデルを使用します。",
    "分别加密保存各服务商的密钥。所选服务商已配置时优先使用；否则使用原 AI 模型。请求失败时不自动切换服务。使用量与费用以服务商套餐为准。": "キーは提供元ごとに個別に暗号化して保存します。選択したサービスが設定済みなら優先使用し、それ以外は元の AI モデルを使用します。失敗時は自動で切り替えません。利用量と料金は提供元のプランに従います。",
    "translation_access": "翻訳リクエストが拒否されました。API キー、Azure リージョン、API の有効化、サブスクリプションを確認してください。",
