    "请选择模型": "모델 선택",
    "请在设置页选择可用的模型。": "설정에서 사용 가능한 모델을 선택하세요.",
    "请在设置页配置所选提供商及模型。": "설정에서 제공업체와 모델을 구성하세요.",
    "输入 API Key，仅加密保存在本机": "API 키 입력. 이 컴퓨터에만 암호화하여 저장",
