    "使用已授权的 ChatGPT 订阅额度。": "승인된 ChatGPT 구독 할당량을 사용합니다.",
    "Gemini API 免费层取决于项目和模型；已启用计费的项目可能产生费用，不使用网页订阅额度。": "Gemini API 무료 할당량은 프로젝트와 모델에 따라 다릅니다. 결제가 활성화된 프로젝트는 요금이 발생할 수 있으며 웹 구독 할당량을 사용하지 않습니다.",
    "Claude API 通常另行计费，不包含在 Claude Free、Pro 或 Max 网页订阅中。": "Claude API는 일반적으로 별도 과금되며 Claude Free, Pro, Max 웹 구독에 포함되지 않습니다.",
    "请在设置页填写所选提供商的 API Key。": "설정에서 선택한 제공업체의 API 키를 입력하세요.",
    "API Key 无效，请检查并重新保存。": "API 키가 유효하지 않습니다. 확인 후 다시 저장하세요.",
    "API 权限不足，请检查密钥、项目、地区或账户权限。": "API 접근 권한이 부족합니다. 키, 프로젝트, 지역 및 계정 권한을 확인하세요.",
    "API 额度不足或请求过多，请查看提供商用量与计费设置。": "API 할당량이 부족하거나 요청이 너무 많습니다. 제공업체 사용량과 결제 설정을 확인하세요.",
    "所选 API 模型不可用，请在设置页重新选择。": "선택한 API 모델을 사용할 수 없습니다. 설정에서 다시 선택하세요.",
    "提供商拒绝了请求，请检查所选模型是否支持文字生成。": "제공업체가 요청을 거부했습니다. 모델이 텍스트 생성을 지원하는지 확인하세요.",
    "无法连接 API，请检查网络后重试。": "API에 연결할 수 없습니다. 네트워크를 확인하고 다시 시도하세요.",
    "API 服务暂时不可用，请稍后重试。": "API 서비스를 일시적으로 사용할 수 없습니다. 나중에 다시 시도하세요.",
    "未获得完整可用的文字结果，可能被安全策略阻止。": "완전한 텍스트 결과를 받지 못했습니다. 안전 정책으로 차단되었을 수 있습니다.",
    "提供商设置无效，请在设置页重新选择。": "제공업체 설정이 올바르지 않습니다. 설정에서 다시 선택하세요.",
    "软件按原样提供，不作任何保证；责任限制以 MIT 许可证为准。使用 各模型 服务仍须遵守其适用条款。": "소프트웨어는 보증 없이 있는 그대로 제공됩니다. 책임 제한은 MIT 라이선스에 따릅니다. 각 모델 서비스 이용에는 해당 이용 약관도 적용됩니다.",
    "邮箱 AI 助手": "Mail AI Assist",
    "摘要、翻译、添加标签和辅助撰写邮件。": "AI로 메일 요약, 번역, 태그 지정 및 작성을 돕습니다.",
    "AI 摘要": "AI 요약",
    "AI 翻译": "메일 번역",
    "AI 自动添加标签": "AI 자동 태그 지정",
    "自动识别原文": "원문 언어 자동 감지",
    "仅发送当前邮件主题和正文，不处理附件。AI 结果请自行核对。": "현재 메일의 제목과 본문만 전송하며 첨부 파일은 처리하지 않습니다. AI 결과를 확인하세요. 태그 생성 시 기존 태그를 우선 사용하기 위해 태그 이름도 전송합니다.",
    "撤销标签": "태그 실행 취소",
    "重试": "다시 시도",
