    "处理完成。": "처리가 완료되었습니다.",
    "标签已添加；原有标签保持不变。": "태그를 추가했습니다. 기존 태그는 유지되었습니다.",
    "本次添加的标签已撤销。": "이번에 추가한 태그를 취소했습니다.",
