    "invalid_tags": "태그가 올바르지 않습니다. 한 줄에 하나씩 1~5개, 각각 최대 32자로 입력하세요. 꺾쇠 괄호와 제어 문자는 사용할 수 없습니다.",
    "mail_operation_failed": "작업에 실패했습니다. 메일, 연결 및 제공업체 설정을 확인한 후 다시 시도하세요.",
    "model_required": "먼저 설정에서 제공업체와 모델을 선택하세요.",
    "Continue with ChatGPT": "ChatGPT로 계속",
    "默认翻译为语言": "기본 번역 대상 언어",
    "默认 AI 标签语言": "기본 AI 태그 언어",
    "邮件翻译自动识别原文语言；摘要使用界面语言。": "번역은 원문 언어를 자동 감지하며 요약은 표시 언어를 사용합니다.",
    "用于之后自动生成的标签，不修改已有标签。": "앞으로 자동 생성할 태그에 적용되며 기존 태그는 변경하지 않습니다.",
    "新邮件自动标签": "새 메일 자동 태그 지정",
    "仅对勾选账户收件箱中新收到的邮件自动添加标签，新账户默认关闭，不扫描历史邮件。使用当前提供商、模型及标签语言；启用后会自动发送邮件主题和正文，消耗套餐或 API 额度。": "선택한 계정의 받은편지함에 새로 도착한 메일에만 자동으로 태그를 지정합니다. 새 계정은 기본적으로 꺼져 있으며 기존 메일은 검색하지 않습니다. 현재 제공업체, 모델 및 태그 언어를 사용합니다. 활성화하면 제목과 본문을 자동 전송하여 구독 또는 API 할당량을 사용합니다.",
    "没有可用的邮件账户。": "사용 가능한 메일 계정이 없습니다.",
    "无法读取账户列表。": "계정 목록을 불러올 수 없습니다.",
    "最近自动标签处理成功。": "최근 자동 태그 지정에 성공했습니다.",
    "最近自动标签处理失败，请检查设置或手动重试。": "최근 자동 태그 지정에 실패했습니다. 설정을 확인하거나 수동으로 다시 시도하세요.",
    "在邮箱主界面右键账户名称，选择“AI 助手 → 自动标记新邮件”以开启或关闭。仅处理已启用账户收件箱的新邮件，新账户默认关闭，不扫描历史邮件。使用当前提供商、模型及标签语言；启用后自动发送邮件主题和正文，消耗套餐或 API 额度。": "메일 기본 화면에서 계정 이름을 오른쪽 클릭하고 'AI 도우미 → 새 메일 자동 태그 지정'으로 켜거나 끄세요. 활성화된 계정의 받은편지함 새 메일만 처리합니다. 새 계정은 기본적으로 꺼져 있으며 기존 메일은 검색하지 않습니다. 현재 제공업체, 모델 및 태그 언어를 사용하며 제목과 본문을 자동 전송하여 구독 또는 API 할당량을 사용합니다.",
    "模型提供商": "모델 제공업체",
    "模型与登录": "모델 및 로그인",
