    "选择原文语言或自动识别；摘要使用界面语言。": "원문 언어 또는 자동 감지를 선택하세요. 요약은 표시 언어를 사용합니다.",
    "标签": "태그",
    "关于与许可证": "정보 및 라이선스",
    "辅助程序更新已下载。点击安装后，请关闭 Thunderbird，再确认管理员授权。": "도우미 업데이트를 다운로드했습니다. 설치를 클릭하고 Thunderbird를 종료한 후 관리자 권한을 승인하세요.",
    "安装辅助程序更新": "도우미 업데이트 설치",
    "请关闭 Thunderbird，随后确认管理员授权以安装更新。": "Thunderbird를 종료하고 관리자 권한을 승인하여 업데이트를 설치하세요.",
    "确认添加标签": "태그 추가 확인",
    "标签建议可修改，每行一个，最多 5 个，每个不超过 32 个字符。确认后才会添加。": "태그 제안은 편집할 수 있습니다. 한 줄에 하나씩 최대 5개, 각각 최대 32자입니다. 확인 후에만 추가됩니다.",
    "目标桌面应用": "대상 데스크톱 앱",
    "其他应用（手动附加）": "다른 앱(수동 첨부)",
