    "ChatGPT 自动附加为实验功能；其他应用只打开程序，需手动添加文件。": "대상 앱을 열고 폴더에서 내보낸 파일을 표시합니다. 채팅을 선택한 후 직접 파일을 첨부하세요.",
    "文件格式": "파일 형식",
    "包含引用回复和转发内容": "인용된 답장 및 전달 내용 포함",
    "请检查预览。EML 为重新生成的邮件文件；不包含原邮件附件。": "미리 보기를 확인하세요. EML은 다시 생성한 메일 파일이며 원본 첨부 파일은 포함하지 않습니다.",
    "内容预览": "내용 미리 보기",
    "文件附加时可能立即上传。项目和聊天由你手动选择，程序不会发送消息。": "파일을 첨부하면 즉시 업로드될 수 있습니다. 프로젝트와 채팅은 직접 선택하세요. 프로그램은 메시지를 보내지 않습니다.",
    "生成文件并打开应用": "파일 생성 후 앱 열기",
