    "导出文件路径": "내보낸 파일 경로",
    "正在准备文件…": "파일 준비 중…",
    "请在 ChatGPT 中选择项目和聊天，然后点击“添加到已选聊天”。": "{app}에서 프로젝트와 채팅을 선택한 후 '선택한 채팅에 첨부'를 클릭하세요.",
    "文件已生成。请在目标应用中手动附加此文件。": "파일을 생성했습니다. 대상 앱에서 직접 첨부하세요.",
    "应用未能自动打开，请手动打开。": "앱을 자동으로 열지 못했습니다. 직접 여세요.",
    "正在附加文件…": "파일 첨부 중…",
    "已检测到附件。请检查目标聊天和上传状态；消息尚未发送。": "첨부 파일을 감지했습니다. 대상 채팅과 업로드 상태를 확인하세요. 메시지는 아직 보내지 않았습니다.",
    "无法确认附加结果。请检查 ChatGPT；如未附加，请手动添加上方文件，避免重复。": "첨부 결과를 확인하지 못했습니다. {app}을 확인하고 첨부되지 않았다면 위 파일을 직접 추가하세요. 중복 첨부에 주의하세요.",
    "desktop_failed": "데스크톱 작업에 실패했습니다. 도우미 설치와 대상 앱을 확인하세요.",
